effect.shader:
const int MAXIMO_DE_FANTASMAS = 8;

/** A paleta tingida de um fantasma k, rotacionando por hash: cada vidro tinge diferente. */
vec3 corDoFantasma(int k, vec3 base) {
    float h = fract(sin(float(k) * 12.9898) * 43758.5453);
    vec3 roda = vec3(
        sin(h * 6.2831 + 0.0),
        sin(h * 6.2831 + 2.094),
        sin(h * 6.2831 + 4.188)
    ) * 0.5 + 0.5;
    return mix(base, roda, 0.55);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 centro = vec2(0.5 * acAspect, 0.5);
    vec2 fonte = vec2(sourceAt.x * acAspect, sourceAt.y);
    vec2 p = vec2(acScreenNorm.x * acAspect, acScreenNorm.y);

    vec3 corAcumulada = vec3(0.0);
    float alfaAcumulado = 0.0;

    // ================ Halo central: a luz espalhada em volta da fonte ================
    float d = length(p - fonte);
    float halo = exp(-d / max(haloSize * 0.3, 1e-4));
    float miolo = 1.0 - smoothstep(0.0, haloSize * 0.04, d);
    corAcumulada += flareColor.rgb * halo + vec3(1.0) * miolo;
    alfaAcumulado = max(alfaAcumulado, max(miolo, halo * 0.8));

    // ================ Estrela: cos(n·θ), afinada e com alcance que cai suave =========
    if (starLength > 0.0) {
        vec2 v = p - fonte;
        float theta = atan(v.y, v.x) + radians(starAngle);
        int pontas = clamp(int(starPoints + 0.5), 2, 12);
        float rosa = cos(float(pontas) * theta);
        rosa = pow(max(rosa, 0.0), 32.0);                 // afina a ponta
        float queda = exp(-d / max(starLength * 0.35, 1e-4));
        float raio = rosa * queda * 1.5;
        corAcumulada += flareColor.rgb * raio;
        alfaAcumulado = max(alfaAcumulado, raio);
    }

    // ================ Fantasmas: cópias alinhadas no eixo fonte↔centro ===============
    int quantos = clamp(int(ghostCount + 0.5), 0, MAXIMO_DE_FANTASMAS);
    for (int k = 0; k < MAXIMO_DE_FANTASMAS; k++) {
        if (k >= quantos) break;

        // Offsets negativos levam o fantasma pro outro lado do centro: é onde um reflexo de lente de verdade cai.
        float offset = -ghostSpread * (float(k) + 1.0) / float(max(quantos, 1));
        vec2 ponto = mix(centro, fonte, 1.0 - offset);

        float dg = length(p - ponto);
        float raio = ghostSize * (0.6 + 0.6 * fract(sin(float(k) * 7.31) * 43758.5453));
        float disco = 1.0 - smoothstep(raio * 0.4, raio, dg);
        float brilhoDoFantasma = disco * (0.6 - 0.5 * float(k) / float(MAXIMO_DE_FANTASMAS));

        corAcumulada += corDoFantasma(k, flareColor.rgb) * brilhoDoFantasma;
        alfaAcumulado = max(alfaAcumulado, brilhoDoFantasma * 0.6);
    }

    corAcumulada *= brightness;
    float alfa = clamp(alfaAcumulado * brightness, 0.0, 1.0) * flareColor.a;

    vec4 desenhado = vec4(corAcumulada, alfa);
    float saidaAlfa = desenhado.a + original.a * (1.0 - desenhado.a);
    vec3 saidaCor = saidaAlfa > 0.0
        ? (desenhado.rgb * desenhado.a + original.rgb * original.a * (1.0 - desenhado.a)) / saidaAlfa
        : vec3(0.0);

    fragColor = vec4(saidaCor, saidaAlfa);
}
